    'SELECT ap.*,co.commission_rate as cr_rate,ce.commission_rate as center_rate FROM appointments ap JOIN counselors co ON ap.counselor_id=co.id JOIN counseling_centers ce ON ap.center_id=ce.id WHERE ap.id=?'
